package com.example.shortener.agent;
import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.TestPropertySource;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @TestPropertySource(properties={"spring.datasource.url=jdbc:h2:mem:agenttest;DB_CLOSE_DELAY=-1"}) class WorkflowOrchestratorTest { @Autowired WorkflowOrchestrator orchestrator; @Test void successfulWorkflowStopsForApproval(){var r=orchestrator.start(new WorkflowRequest("greenfield","Build a URL shortener",false));assertEquals("AWAITING_APPROVAL",r.status);assertTrue(r.stages.containsKey("tests"));assertEquals("SUCCEEDED",r.stages.get("tests").status());} @Test void failedTestsSafeStopBeforeRelease(){var r=orchestrator.start(new WorkflowRequest("brownfield","Add click analytics",true));assertEquals("SAFE_STOP",r.status);assertFalse(r.stages.containsKey("release-readiness"));} @Test void approvalIsExplicit(){var r=orchestrator.start(new WorkflowRequest("ambiguous","Support vanity aliases? clarify uniqueness and ownership",false));var approved=orchestrator.approve(r.id,true,"reviewer","Reviewed risk list");assertEquals("APPROVED_FOR_RELEASE",approved.status);}}
